<script setup>defineProps({variant:{default:'primary'},size:{default:'md'},fullWidth:Boolean,disabled:Boolean,loading:Boolean,type:{default:'button'}});defineEmits(['click'])</script>
<template><button class="a-button" :class="[`a-button--${variant}`,`a-button--${size}`,{'a-button--full':fullWidth}]" :type="type" :disabled="disabled||loading" :aria-busy="loading||undefined" @click="$emit('click',$event)"><i v-if="loading" class="a-spinner"/><slot v-else name="icon-left"/><slot/><slot name="icon-right"/></button></template>
<style scoped>.a-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:var(--radius-pill);font:600 15px/1 var(--font-core);letter-spacing:-.005em;cursor:pointer;transition:background var(--dur-fast) var(--ease-calm),border-color var(--dur-fast) var(--ease-calm),color var(--dur-fast) var(--ease-calm),transform var(--dur-instant) var(--ease-calm)}.a-button:active{transform:scale(var(--press-scale))}.a-button:disabled{cursor:not-allowed;opacity:.45}.a-button--full{width:100%}.a-button--sm{min-height:40px;padding:0 16px;font-size:14px}.a-button--md{min-height:48px;padding:0 22px}.a-button--lg{min-height:56px;padding:0 28px;font-size:16px}.a-button--primary{border:1px solid transparent;background:var(--action-primary);color:var(--action-primary-fg)}.a-button--primary:hover:not(:disabled){background:var(--action-primary-hover)}.a-button--secondary{border:1px solid var(--border-subtle);background:var(--action-secondary-bg);color:var(--action-secondary-fg)}.a-button--secondary:hover:not(:disabled){background:var(--surface-secondary)}.a-button--ghost{border:1px solid transparent;background:transparent;color:var(--text-secondary)}.a-button--ghost:hover:not(:disabled){background:var(--action-secondary-bg);color:var(--text-primary)}.a-button--danger{border:1px solid var(--border-strong);background:transparent;color:var(--status-destructive)}.a-spinner{width:16px;height:16px;border:2px solid;border-top-color:transparent;border-radius:50%}@media(prefers-reduced-motion:no-preference){.a-spinner{animation:aurora-spin .7s linear infinite}}@media(prefers-reduced-motion:reduce){.a-spinner{border-top-color:currentColor;opacity:.65}}</style>
